215	  }
216	  // BCAST IMM (I-format): no funct7, width defaults to VX (IMM always goes to VX)
217	  when (family === OpFamily.VALU_BCAST && f3 === Funct3Bcast.IMM) {
218	    width := 0.U  // VX
219	  }
220	  // vsetlut (I-format): reads from a VR source register → force VR width so
221	  // the backend routes in_a_vr correctly.
222	  when (family === OpFamily.VALU_LUT &&
223	        (f3 === Funct3Lut.VSETLUT_A || f3 === Funct3Lut.VSETLUT_B)) {
224	    width := 2.U  // VR
225	  }
226	  // Width bits are repurposed for src format in CVT family; skip width check for CVT.
227	  val widthIllegal = (f7Width === 3.U) &&
228	    (family =/= OpFamily.VALU_FP) &&
229	    (family =/= OpFamily.VALU_FP_FMA) &&
230	    (family =/= OpFamily.VALU_CVT)
231	
232	  // ---------- Dtype decode ----------
233	  // BF8 variant from funct7[6] (cvt family) or bf8E5M2 forced
234	  val dtype = WireDefault(VecDType.S8C4)
235	  switch (f7Dtype) {
236	    is (1.U) { dtype := VecDType.FP32C1 }
237	    is (2.U) {
238	      // BF class: BF16 unless BF8 format codes are in play
239	      dtype := VecDType.BF16C2
240	    }
241	  }
242	  // For CVT, override with BF8 variant
243	  when (family === OpFamily.VALU_CVT) {
244	    when (f7Bf8 === 1.U) { dtype := VecDType.BF8E5M2 }
245	    .otherwise           { dtype := VecDType.BF8E4M3  }
246	  }
247	
248	  val dtypeIllegal = (f7Dtype === 3.U)
249	
250	  // ---------- MMA control ----------
251	  val mmaKeep  = WireDefault(false.B)
252	  val mmaLast  = WireDefault(false.B)
253	  val mmaReset = WireDefault(false.B)
254	  when (family === OpFamily.MMA) {
255	    switch (f3) {
256	      is (Funct3Mma.MMA)       { mmaKeep  := f7Sat.asBool }   // reuse sat bit for keep
257	      is (Funct3Mma.MMA_LAST)  { mmaLast  := true.B }
258	      is (Funct3Mma.MMA_RESET) { mmaReset := true.B }
259	    }
260	  }
261	
262	  // ---------- Illegal detection ----------
263	  val illegal = WireDefault(false.B)
264	  when (!familyOK)    { illegal := true.B }
265	  when (!f3Valid)     { illegal := true.B }
266	  when (widthIllegal) { illegal := true.B }
267	  when (dtypeIllegal) { illegal := true.B }
268	
269	  // ---------- Drive outputs ----------
270	  io.illegal := illegal
271	
272	  io.decoded.family    := family
273	  io.decoded.rd        := rdBits
274	  io.decoded.rs1       := rs1Bits
275	  io.decoded.rs2       := rs2Bits
276	  io.decoded.mem_width := f3
277	
278	  io.decoded.mma_keep  := mmaKeep
279	  io.decoded.mma_last  := mmaLast
280	  io.decoded.mma_reset := mmaReset
281	
282	  // VALU control bundle
283	  io.decoded.valu.op       := vecOp
284	  io.decoded.valu.regCls    := width
285	  io.decoded.valu.dtype    := dtype
286	  // For CVT, sat bit is at funct7[3] not funct7[4]
287	  io.decoded.valu.saturate := Mux(family === OpFamily.VALU_CVT, f7CvtSat.asBool, f7Sat.asBool)
288	  // For LUT ops, round[0] carries the bank select (taken from funct3[0]):
289	  //   vlut.A (f3=0) → round=0, vlut.B (f3=1) → round=1
290	  //   vsetlut.A (f3=4) → round=0, vsetlut.B (f3=5) → round=1
291	  io.decoded.valu.round    := Mux(
292	    family === OpFamily.VALU_FP_FMA,
293	    rndS,
294	    Mux(family === OpFamily.VALU_CVT, f7CvtRnd,
295	      Mux(family === OpFamily.VALU_LUT, Cat(0.U(1.W), f3(0)),
296	        f7Round))
297	  )
298	  io.decoded.valu.rs3_idx  := rs3Bits
299	  io.decoded.valu.imm      := immI
300	}
301

